## TK-CORE-001 Config Loader v1.0.0
**Purpose:** Resolve merged runtime config (platform defaults ⊕ vertical config ⊕ tenant overrides) for a company.
**Input:** { company_id, request_id }
**Output:** { ok, request_id, data: { ctx }, error, meta }
**Config:** TK_SUPABASE_URL env + Supabase credential.
**Failure modes:** unknown company_id → error company_not_found; Supabase down → retried 3x then error upstream_unavailable.

parameters.jsCode:
// Merge precedence (low → high): platform defaults → vertical config → tenant settings.
const input = $('When Executed by Another Workflow').first().json;
const company = $('Get Company').first().json;
const vertical = $('Get Vertical Config').first().json;

if (!company || !company.id) {
  return [{ json: { ok: false, request_id: input.request_id, data: null, error: { code: 'company_not_found', message: 'No active company for company_id', retryable: false }, meta: { workflow: 'TK-CORE-001', version: '1.0.0' } } }];
}

const platformDefaults = {
  retry: { max_tries: 3, wait_between_tries_ms: 2000 },
  quiet_hours: { start: '21:00', end: '08:00' },
  ai: { max_conversation_context_messages: 20 },
  timezone: $env.TK_DEFAULT_TIMEZONE,
};

function deepMerge(base, override) {
  const out = { ...base };
  for (const [k, v] of Object.entries(override ?? {})) {
    out[k] = v && typeof v === 'object' && !Array.isArray(v) && base?.[k] && typeof base[k] === 'object' && !Array.isArray(base[k])
      ? deepMerge(base[k], v)
      : v;
  }
  return out;
}

const ctx = deepMerge(deepMerge(platformDefaults, vertical?.config ?? {}), company.settings ?? {});
ctx.company = { id: company.id, name: company.name, country: company.country, timezone: company.timezone, plan: company.plan, branding: company.branding, status: company.status };
ctx.vertical_slug = company.vertical_slug;
ctx.vertical_version = vertical?.version ?? null;

return [{ json: { ok: true, request_id: input.request_id, data: { ctx }, error: null, meta: { workflow: 'TK-CORE-001', version: '1.0.0' } } }];
